# typed: true
# frozen_string_literal: true

module Memex
  class EditFormFieldTextComponent < ApplicationComponent
    attr_reader :value, :field, :readonly

    def initialize(value:, field:, readonly:)
      @value = value
      @field = field
      @readonly = readonly
    end

    memoize def icon
      Primer::Beta::Octicon.new("typography")
    end

    def html
      # value["html"] was generated by the GitHub::Goomba::MemexTextColumnPipeline.to_html method, which produces a
      # sanitized result and so can be declared safe as we do below.
      # The sanitization behaviour is tested in test/models/memex_project_column_value_test.rb.
      @html ||= value["html"].html_safe unless value.nil? # rubocop:disable Rails/OutputSafety
    end

    def raw
      @raw ||= value["raw"] unless value.nil?
    end
  end
end
